"""Tests for the image selection in src/images.py, with images generated by Pillow."""
import io
import random
from typing import Optional

import pytest
import requests
from PIL import Image

import images as images_module
from content import ImageCandidate
from images import EXCLUDED_URL_PATTERN, dhash, hamming, open_image, select_images, to_jpeg
from state import DHASH_MAX_DISTANCE

BASE = "https://example.com/wp-content/uploads/2026/10/"


def pattern_image(seed: int, size: tuple[int, int] = (600, 900)) -> Image.Image:
    """Builds a smooth random image; the same seed gives the same picture at any size."""
    rng = random.Random(seed)
    grid = Image.new("L", (12, 18))
    grid.putdata([rng.randrange(256) for _ in range(12 * 18)])
    return grid.resize(size, Image.Resampling.BICUBIC).convert("RGB")


def encode(image: Image.Image, image_format: str = "JPEG", **options: object) -> bytes:
    """Encodes an image."""
    buffer = io.BytesIO()
    image.save(buffer, format=image_format, **options)
    return buffer.getvalue()


class FakeImageHost:
    """Serves prepared image bytes and records the requests."""

    def __init__(self, files: dict[str, object]) -> None:
        self.files = files
        self.requests: list[tuple[str, Optional[str]]] = []

    def __call__(self, url: str, referer: Optional[str]) -> bytes:
        self.requests.append((url, referer))
        content = self.files[url]
        if isinstance(content, Exception):
            raise content
        return content


def test_resized_copy_has_a_close_hash_and_other_images_do_not() -> None:
    original = pattern_image(1)
    assert hamming(dhash(original), dhash(original.resize((300, 450)))) <= DHASH_MAX_DISTANCE
    assert hamming(dhash(original), dhash(pattern_image(2))) > DHASH_MAX_DISTANCE


def test_select_images_applies_all_filters() -> None:
    seen_hash = dhash(pattern_image(4))
    host = FakeImageHost({
        BASE + "look.jpg": encode(pattern_image(1)),
        BASE + "small.jpg": encode(pattern_image(2, (200, 300))),
        BASE + "wide.jpg": encode(pattern_image(3, (1600, 500))),
        BASE + "look-copy.jpg": encode(pattern_image(1, (800, 1200))),
        BASE + "broken.jpg": requests.ConnectionError("reset"),
        BASE + "corrupt.jpg": b"not an image",
        BASE + "seen.jpg": encode(pattern_image(4)),
    })
    candidates = [ImageCandidate(url=BASE + name) for name in
                  ("look.jpg", "small.jpg", "wide.jpg", "look-copy.jpg", "site-logo.png", "broken.jpg",
                   "corrupt.jpg", "seen.jpg")]
    selection = select_images(candidates, lambda h: h if h == seen_hash else None, max_images=8,
                              referer="https://example.com/post/", fetch=host)
    assert [image.candidate.url for image in selection.images] == [BASE + "look.jpg"]
    assert (selection.images[0].width, selection.images[0].height) == (600, 900)
    assert dict(selection.rejected) == {
        "too small": 1, "aspect ratio": 1, "duplicate in post": 1, "excluded url": 1, "download failed": 2,
        "seen before": 1,
    }
    assert all(referer == "https://example.com/post/" for _, referer in host.requests)
    assert BASE + "site-logo.png" not in [url for url, _ in host.requests]


def test_selection_stops_at_the_image_limit() -> None:
    host = FakeImageHost({BASE + f"{seed}.jpg": encode(pattern_image(seed)) for seed in (5, 6, 7)})
    candidates = [ImageCandidate(url=BASE + f"{seed}.jpg") for seed in (5, 6, 7)]
    selection = select_images(candidates, lambda h: None, max_images=2, fetch=host)
    assert len(selection.images) == 2
    assert dict(selection.rejected) == {"over limit": 1}


def test_downloads_per_post_are_limited(monkeypatch: pytest.MonkeyPatch) -> None:
    monkeypatch.setattr(images_module, "MAX_CANDIDATE_DOWNLOADS", 2)
    host = FakeImageHost({BASE + f"{n}.jpg": encode(pattern_image(n, (100, 100))) for n in range(4)})
    selection = select_images([ImageCandidate(url=BASE + f"{n}.jpg") for n in range(4)], lambda h: None,
                              max_images=8, fetch=host)
    assert dict(selection.rejected) == {"too small": 2, "download limit": 2}
    assert len(host.requests) == 2


def test_exif_orientation_is_applied() -> None:
    exif = Image.Exif()
    exif[0x0112] = 6  # rotate 90 degrees clockwise for display
    image = open_image(encode(pattern_image(8, (600, 900)), exif=exif))
    assert image.size == (900, 600)


def test_transparent_images_become_rgb() -> None:
    rgba = Image.new("RGBA", (500, 500), (255, 0, 0, 0))
    assert open_image(encode(rgba, "PNG")).mode == "RGB"


def test_jpeg_for_the_model_is_resized() -> None:
    with Image.open(io.BytesIO(to_jpeg(pattern_image(9, (2000, 3000))))) as image:
        assert max(image.size) == 1024


@pytest.mark.parametrize(
    ("url", "excluded"),
    [
        ("https://example.com/uploads/site-logo.png", True),
        ("https://example.com/icons/heart.jpg", True),
        ("https://example.com/favicon.ico", True),
        ("https://secure.gravatar.com/avatar/abc.jpg", True),
        ("https://example.com/spinner.gif?v=2", True),
        ("https://example.com/uploads/silicone-dress.jpg", False),
        ("https://example.com/uploads/pixelated-print-skirt.jpg", False),
    ],
)
def test_excluded_url_pattern(url: str, excluded: bool) -> None:
    assert bool(EXCLUDED_URL_PATTERN.search(url)) is excluded
